<?php
use App\Http\Controllers\Web\AdminController; use App\Http\Controllers\Web\VehicleMaintenanceController; use Illuminate\Contracts\View\View; use Illuminate\Support\Facades\Route;
Route::get('/',function():View{return view('home',['healthUrl'=>route('api.health'),'databaseUrl'=>Route::has('api.database')?route('api.database'):null,'vehiclesUrl'=>url('/api/v1/vehicles')]);})->name('home');
Route::get('/admin',[AdminController::class,'index'])->middleware(['auth','permission:accounts.manage'])->name('admin.index');
Route::middleware(['auth','permission:vehicles.view'])->group(function (): void { Route::get('/vehicles/{vehicle}/maintenance',[VehicleMaintenanceController::class,'show'])->name('vehicles.maintenance.show'); Route::post('/vehicles/{vehicle}/maintenance/histories',[VehicleMaintenanceController::class,'storeHistory'])->middleware('permission:vehicles.create')->name('vehicles.maintenance.histories.store'); Route::post('/vehicles/{vehicle}/maintenance/plans',[VehicleMaintenanceController::class,'storePlan'])->middleware('permission:vehicles.create')->name('vehicles.maintenance.plans.store'); });
